        require(address(this).balance >= a + b);
        c.deposit{value: a}();
        c.deposit{value: b}();
        // withdrawing as another account should be impossible via this path,
        // but the key observable: total balance grew by a+b
        require(address(c).balance == a + b);
        c.withdraw(a + b);
        uint256 balAfter = address(c).balance;
